data.CommandLine:
"C:\Users\o-neo\.cache\codex-runtimes\codex-primary-runtime\dependencies\native\powershell\pwsh.exe" -NoProfile -Command "try { [Console]::OutputEncoding=[System.Text.Encoding]::UTF8 } catch {}
$now = Get-Date
'USER_CONTEXT_AND_PYTHON_PATHS'
[pscustomobject]@{CollectedAt=$now.ToString('o');User=[Security.Principal.WindowsIdentity]::GetCurrent().Name} | Format-List
Get-Command python,python3,py -All -ErrorAction SilentlyContinue | Select-Object Name,CommandType,Source,Path,Version | Format-Table -AutoSize
where.exe python 2>&1
where.exe py 2>&1

'PYTHON_BINARY_METADATA'
$pythonCandidates = @(
  'C:\Tools\Python313\python.exe',
  'C:\Tools\Python313\pythonw.exe',
  'C:\Users\o-neo\AppData\Local\Microsoft\WindowsApps\python.exe',
  'C:\Users\o-neo\AppData\Local\Microsoft\WindowsApps\python3.exe'
)
foreach ($pythonCandidate in $pythonCandidates) {
  if (Test-Path -LiteralPath $pythonCandidate) {
    $item = Get-Item -LiteralPath $pythonCandidate
    [pscustomobject]@{
      Path = $item.FullName
      Length = $item.Length
      CreationTime = $item.CreationTime.ToString('o')
      LastWriteTime = $item.LastWriteTime.ToString('o')
      FileVersion = $item.VersionInfo.FileVersion
      ProductName = $item.VersionInfo.ProductName
      ProductVersion = $item.VersionInfo.ProductVersion
      CompanyName = $item.VersionInfo.CompanyName
      OriginalFilename = $item.VersionInfo.OriginalFilename
    } | Format-List
  }
}

'RELIABILITY_RECORDS_PYTHON'
try {
  Get-CimInstance -ClassName Win32_ReliabilityRecords -ErrorAction Stop |
    Where-Object { $_.TimeGenerated -ge [datetime]'2026-09-14T00:15:00+03:00' -and ($_.ProductName -match '(?i)python' -or $_.Message -match '(?i)python\.exe|0xc000070a') } |
    Select-Object TimeGenerated,SourceName,EventIdentifier,ProductName,RecordNumber,Message |
    Format-List
} catch {
  \"RELIABILITY_INACCESSIBLE: $($_.Exception.Message)\"
}

'FRESH_WER_AND_DUMPS'
$roots = @(
  'C:\Users\o-neo\AppData\Local\Microsoft\Windows\WER',
  'C:\Users\o-neo\AppData\Local\CrashDumps',
  'C:\ProgramData\Microsoft\Windows\WER\ReportArchive',
  'C:\ProgramData\Microsoft\Windows\WER\ReportQueue'
)
foreach ($rootPath in $roots) {
  if (Test-Path -LiteralPath $rootPath) {
    \"ROOT $rootPath\"
    try {
      Get-ChildItem -LiteralPath $rootPath -Recurse -Force -ErrorAction Stop |
        Where-Object { $_.LastWriteTime -ge [datetime]'2026-09-14T00:15:00+03:00' } |
        Sort-Object LastWriteTime |
        Select-Object FullName,Length,CreationTime,LastWriteTime |
        Format-Table -AutoSize
    } catch {
      \"WER_ROOT_INACCESSIBLE $rootPath: $($_.Exception.Message)\"
    }
  }
}

'FRESH_PYTHON_PREFETCH'
$prefetchRoot = 'C:\Windows\Prefetch'
if (Test-Path -LiteralPath $prefetchRoot) {
  try {
    Get-ChildItem -LiteralPath $prefetchRoot -Filter 'PYTHON*.pf' -Force -ErrorAction Stop |
      Sort-Object LastWriteTime -Descending |
      Select-Object -First 20 FullName,Length,CreationTime,LastWriteTime |
      Format-Table -AutoSize
  } catch {
    \"PREFETCH_INACCESSIBLE: $($_.Exception.Message)\"
  }
}"

